import { Group, Mesh, MeshPhysicalMaterial, DirectionalLight, PlaneGeometry, Shape, ExtrudeGeometry, Vector3, Color, DoubleSide } from 'three/webgpu';
import { mix, color, add, mul, texture, uv, vec3, vec4, sin, cos, pow, clamp, NodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { depthRotate } from '@/primitives';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} textContent
 * @property {Array} cinematicPrimitives
 * @property {Object} visual
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Function} textureLoader
 * @property {Function} fontAtlas
 */

/**
 * Create an equilateral triangle shape centered at the origin.
 * @param {number} side length of each side
 * @returns {Shape}
 */
function createEquilateralTriangle(side) {
    const h = Math.sqrt(3) * side / 2;
    const shape = new Shape();
    shape.moveTo(-side / 2, -h / 3);
    shape.lineTo(side / 2, -h / 3);
    shape.lineTo(0, (2 * h) / 3);
    shape.closePath();
    return shape;
}

/**
 * Gradient texture node for caustic plane.
 * @param {Array} stops array of {at:number, color:string}
 * @returns {NodeMaterial}
 */
function createGradientMaterial(stops, opacity) {
    // linear gradient along X (u)
    const grad = stops.reduce((acc, stop, i) => {
        const col = new Color(stop.hex);
        const colNode = color(col);
        const t = stop.at;
        const weight = clamp(1 - Math.abs(uv().x - t) * 1000, 0, 1);
        return i === 0 ? mul(colNode, weight) : add(acc, mul(colNode, weight));
    }, vec3(0));

    const mat = new NodeMaterial();
    mat.color = mul(grad, opacity);
    mat.transparent = true;
    mat.side = DoubleSide;
    return mat;
}

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Group}
 */
export default function createNode(config, ctx) {
    const root = new Group();
    root.position.set(0, 0, 0);
    root.rotation.set(0, 0, 0);
    root.scale.set(1, 1, 1);

    // ------- Prism -------
    const prismSide = 1.2;
    const prismLength = 1.8;
    const prismShape = createEquilateralTriangle(prismSide);
    const prismGeometry = new ExtrudeGeometry(prismShape, {
        depth: prismLength,
        bevelEnabled: false,
        steps: 1,
    });

    // rotate geometry to align length along X axis, then apply spec rotations
    prismGeometry.rotateY(Math.PI / 2); // make length along X
    const prism = new Mesh(prismGeometry);
    prism.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
    prism.material = new MeshPhysicalMaterial({
        transmission: 1.0,
        thickness: 0.9,
        ior: 1.55,
        roughness: 0.08,
        clearcoat: 0.25,
        clearcoatRoughness: 0.1,
        attenuationColor: new Color('#e8ecf2'),
        attenuationDistance: 2.5,
        iridescence: 1.0,
        iridescenceIOR: 1.3,
        iridescenceThicknessRange: [120, 480],
        side: DoubleSide,
        // Approximate dispersion via iridescence; detailed dispersion would need custom node shader.
    });
    root.add(prism);

    // ------- Emissive Core (Octahedron) -------
    const coreGeom = new THREE.OctahedronGeometry(0.35);
    const coreMat = new MeshPhysicalMaterial({
        color: new Color('#ff2a38'),
        emissive: new Color('#ff2a38'),
        emissiveIntensity: 2.2,
        side: DoubleSide,
        transparent: true,
        opacity: 0.9,
    });
    const core = new Mesh(coreGeom, coreMat);
    core.position.set(0, 0, 0);
    root.add(core);

    // ------- Caustic Streak Plane -------
    const causticGeom = new PlaneGeometry(2.4, 0.5);
    const causticPlane = new Mesh(causticGeom);
    causticPlane.rotation.x = -Math.PI / 2;
    causticPlane.position.y = -1.1;
    const gradientStops = [
        { at: 0.2, hex: '#ff2a38' },
        { at: 0.5, hex: '#e8ecf2' },
        { at: 0.8, hex: '#9fb0c4' },
    ];
    const causticMat = createGradientMaterial(gradientStops, 0.35);
    causticPlane.material = causticMat;
    root.add(causticPlane);

    // ------- Rim Light -------
    const rimLight = new DirectionalLight(0xffffff, 2);
    rimLight.position.set(-5, 2, -5); // behind-left
    rimLight.target = prism;
    root.add(rimLight);
    root.add(rimLight.target);

    // ------- Text -------
    const fontAtlas = ctx.fontAtlas;
    const headline = createText({
        text: 'Light, machined.',
        fontSize: 68,
        fontWeight: 600,
        fontFamily: 'Lora',
        letterSpacing: -0.005,
        lineHeight: 1.1,
        color: '#e8ecf2',
        atlas: 0,
        sourceRect: [0, 0, 512, 320],
    }, fontAtlas);
    headline.position.set(0, -1.75, 0);
    root.add(headline);

    const caption = createText({
        text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
        fontSize: 18,
        fontWeight: 400,
        fontFamily: 'JetBrains Mono',
        letterSpacing: 0.08,
        lineHeight: 1.4,
        color: '#e8ecf2',
        atlas: 0,
        sourceRect: [0, 0, 512, 320],
    }, fontAtlas);
    caption.position.set(0, -2.25, 0);
    root.add(caption);

    // ------- GSAP Timeline for hover interaction -------
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline.to(prism.rotation, {
        y: prism.rotation.y + THREE.MathUtils.degToRad(10),
        duration: 0.35,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    });

    const settleTimeline = gsap.timeline({ paused: true });
    settleTimeline.to(prism.rotation, {
        y: prism.rotation.y,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onComplete: () => {
            // reset to base rotation
            prism.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
        },
    });

    // Store handlers in userData for external use
    root.userData.handlers = {
        onPointerEnter: () => {
            hoverTimeline.play(0);
        },
        onPointerLeave: () => {
            hoverTimeline.reverse();
            settleTimeline.restart();
        },
    };

    // Apply cinematic primitive depth-rotate (already handled via handlers, but also invoke)
    if (config.cinematicPrimitives) {
        config.cinematicPrimitives.forEach((prim) => {
            if (prim.name === 'depth-rotate') {
                ctx.primitives[prim.name](root, prim.params);
            }
        });
    }

    // Cleanup
    root.userData.cleanup = () => {
        hoverTimeline.kill();
        settleTimeline.kill();

        prismGeometry.dispose();
        prism.material.dispose();

        coreGeom.dispose();
        coreMat.dispose();

        causticGeom.dispose();
        if (causticMat.dispose) causticMat.dispose();

        rimLight.dispose();

        if (headline.geometry) headline.geometry.dispose();
        if (headline.material) headline.material.dispose();

        if (caption.geometry) caption.geometry.dispose();
        if (caption.material) caption.material.dispose();
    };

    return root;
}
